def clean(df):
    if df.duplicated().any():
        pass
    allowed_species = ['Adelie', 'Chinstrap', 'Gentoo']
    df = df[df['species'].isin(allowed_species)]
    df = df[(df['flipper_length_mm'] >= 170) & (df['flipper_length_mm'] <= 235)]
    return df

def answer(df):
    grouped = df.groupby('species')['flipper_length_mm'].mean().reset_index()
    result = {}
    for name, row in grouped.iterrows():
        result[name] = row['flipper_length_mm']
    return result
